// MODE: 'keys' | 'glossary' | 'mt' | 'evidence' | 'languages' | 'statuses'
const MODE = 'statuses';

const BASE = 'https://api.lokalise.com/api2';
const GLOSS_PID = '46552447679363c70f7ef8.58193285';

// The 13 projects that the 471 auto-fix strings live in.
const FIX_PROJECTS = [
  ['31393214664f295f94dd86.76792605','Personality.co'],
  ['7497898368b56f1d07ee46.54496723','MyImage - html/legal pages'],
  ['901014606819db6d0bc999.26230201','Mobitrace - html/legal pages'],
  ['18564477693fc9bba4cec8.54789459','My QR Code html'],
  ['46919453689d5d729a1e70.59972091','PDF Editor - html/legal pages'],
  ['491848986923fad6dc2f85.42477363','QRcreate'],
  ['964775386a3ce03ecca883.03770715','Realchecker (FE)'],
  ['6744586768821f2c3fe845.13636914','PDF Editor (BE- emails)'],
  ['3070657967b5854be32cb1.65162854','My Image'],
  ['9933660066825e9a8005c8.58526829','Personality - Members area content'],
  ['9274956467e3e224807498.79791832','Mobitrace - backend/emails'],
  ['60625870676151e1da46d0.81913446','My QR Code'],
  ['1286096867dbf31146afc5.54950617','PDF Editor']
];

if (MODE === 'statuses') {
  return FIX_PROJECTS.map(function (p) {
    return { json: { mode: 'statuses', project_id: p[0], project_name: p[1],
      url: BASE + '/projects/' + p[0] + '/custom_translation_statuses?limit=100' } };
  });
}

if (MODE === 'languages') {
  return [{ json: { mode: 'languages', project_id: GLOSS_PID,
    project_name: 'Multiproject/shared - GLOSSARY',
    url: BASE + '/projects/' + GLOSS_PID + '/languages?limit=500&pagination=cursor' } }];
}

if (MODE === 'glossary') {
  return [{ json: { mode: 'glossary', target: 'th',
    project_id: GLOSS_PID, project_name: 'Multiproject/shared - GLOSSARY',
    url: BASE + '/projects/' + GLOSS_PID + '/glossary-terms?limit=500&pagination=cursor' } }];
}

return [{ json: { mode: MODE, note: 'other modes unchanged' } }];

const pages = $input.all();
const cfgAll = $('Config').all().map(function (x) { return x.json; });
const cfg = cfgAll[0] || {};
const mode = cfg.mode || 'keys';
const NAMES = {};
cfgAll.forEach(function (c) { if (c.project_id) NAMES[c.project_id] = c.project_name || c.project_id; });

const errors = [];
const bodies = [];
pages.forEach(function (p) {
  const r = p.json || {};
  if (r.error !== undefined && r.body === undefined) {
    errors.push({ kind: 'item_error', detail: String(JSON.stringify(r.error)).slice(0, 400) });
    return;
  }
  const st = r.statusCode;
  const b = (r.body !== undefined) ? r.body : r;
  if (st !== undefined && st !== 200) {
    errors.push({ kind: 'http', status: st, body: (typeof b === 'string' ? b : JSON.stringify(b)).slice(0, 400) });
    return;
  }
  bodies.push(b);
});

if (mode === 'statuses') {
  const out = [];
  bodies.forEach(function (b) {
    const pid = String(b.project_id || '');
    const list = b.custom_translation_statuses || [];
    out.push({ project: NAMES[pid] || pid, project_id: pid,
      count: list.length,
      statuses: list.map(function (s) { return { id: s.status_id, title: s.title, color: s.color }; }),
      has_mt_to_review: list.some(function (s) { return String(s.title).trim() === 'MT_to_review'; }),
      mt_to_review_id: (list.filter(function (s) { return String(s.title).trim() === 'MT_to_review'; })[0] || {}).status_id || null });
  });
  return [{ json: { mode: 'statuses', pages: pages.length, errors: errors,
    projects: out.length,
    missing_mt_to_review: out.filter(function (x) { return !x.has_mt_to_review; }).map(function (x) { return x.project; }),
    detail: out } }];
}

if (mode === 'languages') {
  const out = [];
  bodies.forEach(function (b) {
    (b.languages || []).forEach(function (l) { out.push({ id: l.lang_id, iso: l.lang_iso, name: l.lang_name }); });
  });
  out.sort(function (a, b) { return a.id - b.id; });
  return [{ json: { mode: 'languages', pages: pages.length, errors: errors, count: out.length, languages: out } }];
}

if (mode === 'glossary') {
  const terms = [];
  bodies.forEach(function (b) {
    (b.data || b.glossary_terms || []).forEach(function (t) {
      const tr = {};
      (t.translations || []).forEach(function (x) {
        tr[x.langId || x.lang_id] = { t: x.translation || '', d: x.description || '' };
      });
      terms.push({ id: t.id, term: t.term || '', desc: t.description || '',
        translatable: t.translatable, forbidden: t.forbidden,
        tags: (t.tags || []).join('|'), translations: tr });
    });
  });
  return [{ json: { mode: 'glossary', pages: pages.length, errors: errors, count: terms.length, terms: terms } }];
}

return [{ json: { mode: mode, errors: errors, note: 'no shaper for this mode' } }];
